def separate_paren_groups(paren_string: str) -> List[str]:
    cleaned = paren_string.replace(" ", "")
    groups: List[str] = []
    current = ""
    depth = 0
    for ch in cleaned:
        if ch not in ("(", ")"):
            continue
        current += ch
        if ch == "(":
            depth += 1
        else:  # ch == ")"
            depth -= 1
            if depth < 0:
                raise ValueError("Unbalanced parentheses detected.")
            if depth == 0:
                groups.append(current)
                current = ""
    if depth != 0:
        raise ValueError("Unbalanced parentheses detected at end of string.")
    return groups

def count_partitions(n:int, k:int, x:int)->int:
    """
    Count integer partitions of n into k parts each >= x, order doesn't matter.
    """
    # Validate
    if any(not isinstance(v, int) for v in (n,k,x)) or n<0 or k<0 or x<0:
        raise ValueError('Parameters must be non-negative integers')
    if k==0:
        return int(n==0)
    m=n - k*x
    if m<0:
        return 0
    # DP
    dp=[[0]*(k+1) for _ in range(m+1)]
    for j in range(k+1): dp[0][j]=1
    for i in range(1,m+1):
        for j in range(1,k+1):
            dp[i][j]=dp[i][j-1]
            if i>=j:
                dp[i][j]+=dp[i-j][j]
    return dp[m][k]
